    <div className="lg:pl-[254px]"><header className="sticky top-0 z-20 flex h-[70px] items-center justify-between border-b border-border bg-background/90 px-4 backdrop-blur-md sm:px-7"><div className="flex items-center gap-3"><button onClick={() => setMobileOpen(true)} data-testid="button-open-menu" className="rounded-xl p-2 hover:bg-muted lg:hidden"><Menu className="h-5 w-5" /></button><div className="lg:hidden"><Logo /></div><div className="hidden items-center gap-2 text-sm text-muted-foreground lg:flex"><span>Workspace</span><ChevronRight className="h-4 w-4" /><span className="font-semibold text-foreground">{title}</span></div></div><div className="flex items-center gap-2"><button onClick={() => setSearchOpen(true)} data-testid="button-open-search" className="flex h-10 items-center gap-2 rounded-xl border border-border bg-card px-3 text-sm text-muted-foreground transition-colors hover:border-[#2c8c83]"><Search className="h-4 w-4" /><span className="hidden sm:inline">Search anything</span><span className="hidden rounded-md bg-muted px-1.5 py-0.5 font-mono text-[10px] sm:inline">⌘ K</span></button><div className="relative"><button onClick={() => setNotificationsOpen((open) => !open)} aria-expanded={notificationsOpen} data-testid="button-notifications" className="relative rounded-xl p-2.5 text-muted-foreground hover:bg-muted"><Bell className="h-[18px] w-[18px]" />{!notificationsRead && <span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[#e99a4b]" />}</button>{notificationsOpen && <div className="absolute right-0 top-12 z-30 w-[min(340px,calc(100vw-2rem))] rounded-2xl border border-border bg-card p-4 shadow-xl"><div className="flex items-center justify-between"><h2 className="text-sm font-bold">Notifications</h2><button onClick={() => { setNotificationsRead(true); localStorage.setItem('topit-notifications-read', 'true'); }} data-testid="button-mark-notifications-read" className="text-[10px] font-bold text-[#236f69]">Mark all read</button></div><Link onClick={() => setNotificationsOpen(false)} href="/board-updates" data-testid="link-notification-updates" className="mt-3 block rounded-xl bg-secondary/60 p-3 text-xs leading-5 hover:bg-secondary"><strong className="block">Curriculum check</strong>Review the official CBSE curriculum before finalising your study plan.</Link><Link onClick={() => setNotificationsOpen(false)} href="/tests" data-testid="link-notification-tests" className="mt-2 block rounded-xl bg-secondary/60 p-3 text-xs leading-5 hover:bg-secondary"><strong className="block">Practice reminder</strong>Try a short timed demo test when you are ready.</Link><p className="mt-3 text-[10px] text-muted-foreground">Local demo reminders only.</p></div>}</div><Link href="/profile" data-testid="link-profile-header" className="grid h-9 w-9 place-items-center rounded-full bg-[#d5e7df] text-xs font-bold text-[#236f69]">AM</Link></div></header><main className="mx-auto max-w-[1440px] p-4 sm:p-7">{children}</main></div>
